<script setup>
import { computed, reactive, ref, watch } from 'vue';
import { UiButton, UiDrawer, UiSearchSelect } from '@irlix/ui';
import AttemptProgress from './AttemptProgress.vue';

const props=defineProps({lead:{type:Object,default:null},employees:{type:Array,default:()=>[]},contacts:{type:Array,default:()=>[]},requests:{type:Array,default:()=>[]},statuses:{type:Array,default:()=>[]},canManage:Boolean});
const emit=defineEmits(['close','changed','convert','create-request']);
const busy=ref(false),error=ref(''),comment=ref(''),legalOpen=ref(false),contactOpen=ref(false),activeTab=ref('history');
const emptyLegal=()=>({name:'',inn:'',full_name:'',ogrn:'',kpp:'',registration_date:'',okpo:'',oktmo:'',address:''});
const legal=reactive(emptyLegal()),contact=reactive({contact_id:'',full_name:'',position:'',phone:'',email:''});
const employeeMap=computed(()=>new Map(props.employees.map(item=>[Number(item.id),item.full_name||`#${item.id}`])));
const employeeName=id=>employeeMap.value.get(Number(id))||(id?`#${id}`:'—');
const contactOptions=computed(()=>props.contacts.map(item=>({value:String(item.id),label:item.full_name})).sort((a,b)=>a.label.localeCompare(b.label,'ru')));
const leadRequests=computed(()=>props.requests.filter(item=>Number(item.lead_id)===Number(props.lead?.id)));
const activeRequestCount=computed(()=>leadRequests.value.filter(item=>item.status!=='Закрыт').length);
const tabs=computed(()=>[
  {value:'history',label:'История'},
  {value:'requests',label:`Запросы (${activeRequestCount.value})`},
  {value:'contacts',label:'Контакты'},
  {value:'legal',label:'Юр. лица'},
]);
const dateTime=value=>value?new Date(value).toLocaleString('ru-RU',{dateStyle:'short',timeStyle:'short'}):'—';
async function api(url,options={}){const response=await fetch(url,{...options,headers:{Accept:'application/json','Content-Type':'application/json',...(options.headers||{})}});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.message||Object.values(body.errors||{}).flat().join(', ')||`HTTP ${response.status}`);return body;}
async function run(action){busy.value=true;error.value='';try{await action();emit('changed');}catch(e){error.value=e.message||String(e);}finally{busy.value=false;}}
function changeStatus(value){run(()=>api(`/api/clients/leads/${props.lead.id}`,{method:'PATCH',body:JSON.stringify({status:value})}));}
function addComment(){const value=comment.value.trim();if(!value)return;run(async()=>{await api(`/api/clients/leads/${props.lead.id}/comments`,{method:'POST',body:JSON.stringify({comment:value})});comment.value='';});}
function addLegal(){if(!legal.name.trim()||!legal.inn.trim()||!legal.full_name.trim())return;run(async()=>{await api(`/api/clients/leads/${props.lead.id}/legal-entities`,{method:'POST',body:JSON.stringify(Object.fromEntries(Object.entries(legal).map(([key,value])=>[key,value||null])))});Object.assign(legal,emptyLegal());legalOpen.value=false;});}
function addContact(){if(!contact.contact_id&&!contact.full_name.trim())return;run(async()=>{await api(`/api/clients/leads/${props.lead.id}/contacts`,{method:'POST',body:JSON.stringify({contact_id:Number(contact.contact_id)||null,full_name:contact.full_name||null,position:contact.position||null,phone:contact.phone||null,email:contact.email||null})});Object.assign(contact,{contact_id:'',full_name:'',position:'',phone:'',email:''});contactOpen.value=false;});}
watch(()=>props.lead?.id,()=>{error.value='';comment.value='';legalOpen.value=false;contactOpen.value=false;activeTab.value='history';});
</script>

<template>
  <UiDrawer :open="!!lead" :title="lead?`Лид · ${lead.name}`:''" width="46vw" :min-width="360" :z-index="1120" @close="emit('close')">
    <div v-if="lead" class="lead-detail">
      <div v-if="error" class="error-banner">{{error}}</div>
      <section class="lead-facts"><div><small>Название</small><strong>{{lead.name}}</strong></div><div><small>Источник</small><span>{{lead.source||'—'}}</span></div><div><small>Ответственный</small><span>{{employeeName(lead.responsible_employee_id)}}</span></div><label><small>Статус</small><UiSearchSelect :model-value="lead.status" :options="statuses.map(value=>({value,label:value}))" :disabled="!canManage||busy" :clearable="false" @change="changeStatus"/></label></section>
      <nav class="lead-tabs"><button v-for="tab in tabs" :key="tab.value" type="button" :class="{active:activeTab===tab.value}" @click="activeTab=tab.value">{{tab.label}}</button></nav>
      <section v-if="activeTab==='history'" class="lead-section lead-history"><article v-for="event in lead.events||[]" :key="event.id"><i/><div><header><strong>{{event.type==='comment'?'Комментарий':event.status}}</strong><time>{{dateTime(event.created_at)}}</time></header><p v-if="event.comment">{{event.comment}}</p></div></article><div v-if="!(lead.events||[]).length" class="lead-empty">История пока пуста</div><form v-if="canManage" class="comment-form" @submit.prevent="addComment"><input v-model="comment" maxlength="5000" placeholder="Добавить комментарий"><UiButton compact type="submit" :disabled="busy||!comment.trim()">Добавить</UiButton></form></section>
      <section v-else-if="activeTab==='requests'" class="lead-section"><header><h3>Запросы лида</h3><button v-if="canManage&&!lead.converted_client_id" type="button" @click="emit('create-request',lead)">+ Создать запрос</button></header><div class="lead-request-tree"><article v-for="request in leadRequests" :key="request.id" class="lead-request"><header><strong>{{request.title}}</strong><span>{{request.display_status||request.status}}</span></header><div v-for="position in request.positions||[]" :key="position.id" class="lead-position"><div><b>{{position.technology || 'Технология не указана'}}, {{position.level}}</b><small>{{position.display_status||position.status}}</small></div><div v-for="attempt in position.attempts||[]" :key="attempt.id" class="lead-attempt"><AttemptProgress :attempt="attempt"/><span>{{attempt.specialist_name||'Специалист не указан'}}</span><small>{{attempt.status}}</small></div></div></article><div v-if="!leadRequests.length" class="lead-empty">У лида пока нет запросов</div></div></section>
      <section v-else-if="activeTab==='contacts'" class="lead-section"><header><h3>Контакты</h3><button v-if="canManage" type="button" @click="contactOpen=!contactOpen">+ Привязать / создать</button></header><div v-for="item in lead.contacts||[]" :key="item.id" class="compact-row"><strong>{{item.full_name}}</strong><span>{{item.position||item.phone||item.email||'—'}}</span></div><div v-if="!(lead.contacts||[]).length" class="lead-empty">Контакты не добавлены</div><form v-if="contactOpen" class="inline-form contact-form" @submit.prevent="addContact"><label>Существующий контакт<UiSearchSelect v-model="contact.contact_id" :options="contactOptions" placeholder="Не выбран"/></label><span class="or">или новый</span><input v-model="contact.full_name" :disabled="!!contact.contact_id" placeholder="ФИО"><input v-model="contact.position" placeholder="Должность"><input v-model="contact.phone" placeholder="Телефон"><input v-model="contact.email" type="email" placeholder="Email"><UiButton compact type="submit" :disabled="busy">Добавить</UiButton></form></section>
      <section v-else class="lead-section"><header><h3>Юридические лица</h3><button v-if="canManage" type="button" @click="legalOpen=!legalOpen">+ Добавить</button></header><div v-for="item in lead.legal_entities||[]" :key="item.id" class="compact-row"><div><strong>{{item.name}}</strong><small>{{item.full_name||'—'}}</small></div><span>{{item.inn||'ИНН не указан'}}</span></div><div v-if="!(lead.legal_entities||[]).length" class="lead-empty">Юридические лица не добавлены</div><form v-if="legalOpen" class="inline-form legal-form" @submit.prevent="addLegal"><input v-model="legal.name" required placeholder="Название *"><input v-model="legal.inn" required placeholder="ИНН *"><input v-model="legal.full_name" required class="wide" placeholder="Полное название *"><input v-model="legal.ogrn" placeholder="ОГРН"><input v-model="legal.kpp" placeholder="КПП"><input v-model="legal.registration_date" type="date"><input v-model="legal.okpo" placeholder="ОКПО"><input v-model="legal.oktmo" placeholder="ОКТМО"><input v-model="legal.address" class="wide" placeholder="Адрес"><UiButton compact type="submit" class="wide" :disabled="busy||!legal.name.trim()||!legal.inn.trim()||!legal.full_name.trim()">Сохранить</UiButton></form></section>
      <div class="lead-footer-actions"><UiButton v-if="canManage&&!lead.converted_client_id" variant="secondary" @click="emit('create-request',lead)">Создать запрос</UiButton><UiButton v-if="canManage&&!lead.converted_client_id" @click="emit('convert',lead)">Создать клиента</UiButton></div>
    </div>
  </UiDrawer>
</template>

<style scoped>
.lead-detail{display:grid;gap:16px;color:var(--irlix-color-text);font-size:var(--irlix-font-size-body)}.lead-facts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px 24px}.lead-facts>div,.lead-facts>label{display:grid;align-content:start;gap:2px;min-width:0}.lead-facts small{color:var(--irlix-color-text-muted);font-size:var(--irlix-font-size-caption)}.lead-tabs{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:4px;padding:4px;border-radius:10px;background:var(--irlix-color-surface-muted)}.lead-tabs button{min-height:34px;border:0;border-radius:8px;background:transparent;color:var(--irlix-color-text);font:inherit;font-size:var(--irlix-font-size-caption);font-weight:600;cursor:pointer}.lead-tabs button.active{background:var(--irlix-color-surface);color:var(--irlix-color-text);box-shadow:0 1px 4px rgba(28,37,45,.1)}.lead-section{display:grid;align-content:start;gap:9px;min-height:190px}.lead-section>header{display:flex;align-items:center;justify-content:space-between;gap:12px}.lead-section h3{margin:0;font-size:var(--irlix-font-size-body)}.lead-section>header button{border:0;background:transparent;color:#078d6c;font:inherit;font-size:var(--irlix-font-size-caption);cursor:pointer}.compact-row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:8px 10px;border-radius:8px;background:var(--irlix-color-surface-muted)}.compact-row>div{display:grid;gap:2px}.compact-row small,.compact-row span{color:var(--irlix-color-text-muted);font-size:var(--irlix-font-size-caption)}.inline-form{display:grid;grid-template-columns:1fr 160px auto;gap:8px}.legal-form,.contact-form{grid-template-columns:1fr 1fr}.legal-form .wide{grid-column:1/-1}.contact-form label{display:grid;gap:4px;grid-column:1/-1;color:var(--irlix-color-text);font-size:var(--irlix-font-size-caption)}.contact-form .or{grid-column:1/-1;color:var(--irlix-color-text-muted);font-size:var(--irlix-font-size-caption);text-transform:uppercase}.inline-form input,.comment-form input{min-height:var(--irlix-control-height,32px);padding:0 var(--irlix-control-padding-x,12px);border:1px solid var(--irlix-control-border,#dde1e7);border-radius:var(--irlix-control-radius,10px);outline:0;font:inherit}.inline-form input:focus,.comment-form input:focus{border-color:var(--irlix-color-primary);box-shadow:0 0 0 2px rgba(18,184,144,.1)}.lead-history article{position:relative;display:grid;grid-template-columns:10px 1fr;gap:10px;padding-bottom:12px}.lead-history article:not(:last-of-type):before{content:"";position:absolute;left:3px;top:13px;bottom:0;border-left:1px dashed var(--irlix-color-border)}.lead-history article>i{position:relative;z-index:1;width:7px;height:7px;margin-top:6px;border-radius:50%;background:#aeb6bf}.lead-history article header{display:flex;align-items:baseline;justify-content:space-between;gap:12px}.lead-history article time{color:var(--irlix-color-text-muted);font-size:var(--irlix-font-size-caption)}.lead-history article p{margin:5px 0 0;white-space:pre-wrap}.comment-form{display:grid;grid-template-columns:1fr auto;gap:8px;margin-top:2px}.lead-request-tree{display:grid;gap:9px}.lead-request{padding:10px 12px;border-radius:9px;background:var(--irlix-color-surface-muted)}.lead-request>header{display:flex;justify-content:space-between;gap:12px}.lead-request>header span,.lead-position small,.lead-attempt small{color:var(--irlix-color-text-muted);font-size:var(--irlix-font-size-caption)}.lead-position{display:grid;gap:6px;margin-top:8px;padding-left:14px}.lead-position>div:first-child{display:flex;justify-content:space-between}.lead-attempt{display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:10px;padding-left:14px}.lead-attempt>span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.lead-empty{padding:22px;color:var(--irlix-color-text-muted);text-align:center}.lead-footer-actions{display:flex;justify-content:flex-end;gap:8px}
@media(max-width:720px){.lead-facts,.inline-form,.contact-form{grid-template-columns:1fr}.legal-form .wide{grid-column:auto}.lead-tabs{grid-template-columns:1fr 1fr}.lead-attempt{grid-template-columns:auto 1fr}.lead-attempt small{grid-column:2}}
</style>
